/**
 * TEST ONLY. 4D-SCP v0.1.11 — vector + simulator-input generation for the RTL temporal-only decoder
 * (hw/scp4d/rtl/scp4d_tdec.v). Pure: no I/O, no env, no clocks, no randomness.
 *
 * - New temporal-only golden vectors (rank 0, relations off) are GENERATED by the v0.1.10 integer
 *   model (scripts/scp-v0110-int-scp4d.ts: encodeIntScp4d + decodeIntScp4d), never hand-edited.
 * - The two v0.1.10 environment streams the 2.38 pJ/ef estimate was computed on
 *   (env-16x16x2-T64 / T256, "event-driven temporal-only") are regenerated deterministically; their
 *   sha256 prefixes are pinned against fixtures/scp/v0110-int-report.json by the check.
 * - Sim inputs: one hex byte per line (stream), one 32-bit two's-complement word per line (codes,
 *   frame-major), one 32-bit word per line (event count per frame).
 * - rtlCycleModel(): closed-form cycle count of the RTL as designed (1 byte / cycle front end,
 *   background state clear, sweep cycles for zero/linear sparse frames, fixed pipeline drain). The
 *   check compares it with the simulator's measured count, so the committed report can be
 *   re-verified on a machine without a simulator.
 */
import type { Relation4D, StateSurface4D } from "../src/scp/subsystem";
import { ENV_EPS, ENV_LABEL, FRAME_EPS, frameFixtures, makeEnvironment } from "./scp-v019-env-fixture";
import {
  DECLARED_WIDTHS, DEFAULT_G, decodeIntScp4d, encodeIntScp4d, ingestCodes, signedBits,
  type Census, type FrameEvents, type IntConfig, type IntStreamInput, type RegName,
} from "./scp-v0110-int-scp4d";

export const RTL_ADDR_W = 11;
export const RTL_MAX_D = 2 ** RTL_ADDR_W;
/** Cycles from the last payload byte accepted to `done` observed (token A, B, out, done). */
export const RTL_DRAIN = 4;

export interface TemporalVector {
  id: string; note: string; label: string;
  shape: { nx: number; ny: number; nz: number; channels: number };
  eps_f64_bits: string[]; G: number; config: IntConfig;
  times: number[]; meta: unknown;
  input_codes: number[][];
  expected_bytes_hex: string;
  expected_decoded_codes: number[][];
  expected_events: { positions: number[]; q: number[]; dense: boolean }[];
  register_max_abs: Record<string, number>;
  register_max_bits: Record<string, number>;
  decode_ops: Record<string, number>;
}

const bitsHex = (v: number) => { const b = Buffer.alloc(8); b.writeDoubleLE(v); return Buffer.from(b).reverse().toString("hex"); };
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const widthsOf = (c: Record<string, number>) => Object.fromEntries(Object.keys(c).map((k) => [k, c[k] === 0 ? 0 : signedBits(c[k])]));
const inputOf = (s: StateSurface4D, eps: number[]): IntStreamInput => ({ shape: s.shape, times: s.times, meta: s.meta, eps, relations: s.relations });

/** Same hand-written values as the v0.1.10 edge vector (scripts/check-scp-v0110.ts §9). */
function edgeSurface(): StateSurface4D {
  const vals = [[0, 0.25], [1.37, 0.95], [-2.5, -1.0], [-2.49, -1.0], [3.0, 1.75], [3.0, 1.74], [-0.004, 0.249]];
  const relations: Relation4D[] = [{ target: 1, sources: [0], weights: [0.5], bias: 0.25, kind: "ch1 = 0.5·ch0 + 0.25" }];
  return { shape: { nx: 1, ny: 1, nz: 1, channels: 2 }, channelNames: ["a", "b"], times: vals.map((_, i) => 1_000 + 10 * i),
    frames: vals.map((v) => Float64Array.from(v)), relations, label: "TEST-ONLY hand-written edge cases (negatives, large jumps, near-threshold holds, bias)" };
}
function sliceSurface(s: StateSurface4D, T: number, label: string): StateSurface4D {
  return { ...s, times: s.times.slice(0, T), frames: s.frames.slice(0, T), meta: s.meta ? { steps: s.meta.steps.slice(0, T), verdicts: s.meta.verdicts.slice(0, T) } : undefined, label };
}

type Spec = { id: string; note: string; label: string; surface: StateSurface4D; eps: number[]; cfg: IntConfig };
const TEMPORAL = (predictor: IntConfig["predictor"], G = DEFAULT_G): IntConfig => ({ rank: 0, relations: false, predictor, G });

function specs(): Spec[] {
  const frames = frameFixtures();
  const envSmall = makeEnvironment({ nx: 4, ny: 4, nz: 1, T: 8 });
  return [
    { id: "v0.1-first-16-temporal-last", note: "First 16 frames of the v0.1 fixture; temporal-only (rank 0, relations off), last-value hold; all-dense layout (D=3).", label: "TEST-ONLY hand-written v0.1 fixture (first 16)", surface: sliceSurface(frames[0].surfaceRel, 16, "TEST-ONLY hand-written v0.1 fixture (first 16)"), eps: [...FRAME_EPS], cfg: TEMPORAL("last") },
    { id: "env-4x4x1-T8-temporal-last", note: "Small SYNTHETIC environment; temporal-only, last-value hold (the event-driven path); adaptive sparse/dense frames.", label: ENV_LABEL, surface: envSmall.surface, eps: [...ENV_EPS], cfg: TEMPORAL("last") },
    { id: "env-4x4x1-T8-temporal-linear", note: "Same environment; temporal-only, linear predictor (every element updated every frame: sweep path).", label: ENV_LABEL, surface: envSmall.surface, eps: [...ENV_EPS], cfg: TEMPORAL("linear") },
    { id: "edge-handwritten-G2-temporal-last", note: "The v0.1.10 hand-written edge values at G=2 (deadband 3 grid units); temporal-only, last-value hold.", label: "TEST-ONLY hand-written", surface: edgeSurface(), eps: [0.01, 0.01], cfg: TEMPORAL("last", 2) },
  ];
}

function build(s: Spec): TemporalVector & { _ok: boolean } {
  const codes = ingestCodes(s.surface.frames, s.surface.shape.channels, s.eps, s.cfg.G);
  const r = encodeIntScp4d(inputOf(s.surface, s.eps), codes, s.cfg);
  if (r.cfg.rank !== 0 || r.cfg.relations) throw new RangeError(`${s.id}: not a temporal-only stream`);
  const d = decodeIntScp4d(r.bytes, s.surface.relations);
  const cen = Object.fromEntries((Object.keys(DECLARED_WIDTHS) as RegName[]).map((k) => [k, Math.max(r.census[k], d.census[k])])) as Census;
  return {
    id: s.id, note: s.note, label: s.label, shape: s.surface.shape, eps_f64_bits: s.eps.map(bitsHex), G: r.cfg.G, config: r.cfg,
    times: [...s.surface.times], meta: s.surface.meta ?? null,
    input_codes: codes.map((f) => Array.from(f)),
    expected_bytes_hex: hex(r.bytes),
    expected_decoded_codes: d.codes.map((f) => Array.from(f)),
    expected_events: d.perFrame.map((f) => ({ positions: f.positions, q: f.q, dense: f.dense })),
    register_max_abs: cen, register_max_bits: widthsOf(cen),
    decode_ops: { ...d.ops },
    _ok: d.codes.every((f, t) => f.every((x, e) => x === r.decoded[t][e])),
  };
}

export const TEMPORAL_VECTORS_FORMAT = "4d-scp-v0.1.11-scp4d-int-temporal-golden-vectors";
export function temporalVectorFile(): { file: object; ok: boolean; vectors: TemporalVector[] } {
  const built = specs().map(build);
  const vectors = built.map(({ _ok, ...v }) => v);
  return {
    ok: built.every((v) => v._ok),
    vectors,
    file: {
      format: TEMPORAL_VECTORS_FORMAT,
      version: 1,
      note: "TEST ONLY. Additional bit-accurate reference vectors for the v0.1.11 RTL temporal-only decoder (rank 0, relations off). Generated by the v0.1.10 integer model (scripts/scp-v0110-int-scp4d.ts), not hand-edited. Inputs are labelled test fixtures, not production data. Same S4DI v1 stream format as fixtures/scp/golden-vectors-scp4d.json (unchanged).",
      generator: "scripts/scp-v0111-rtl-vectors.ts (temporalVectorFile)",
      vectors,
    },
  };
}

/** The v0.1.10 report's "event-driven temporal-only" environment streams, regenerated. */
export function envTemporalStreams(): { id: string; T: number; D: number; bytes: Uint8Array; codes: number[][]; perFrame: FrameEvents[]; decode_ops: Record<string, number> }[] {
  return [64, 256].map((T) => {
    const env = makeEnvironment({ nx: 16, ny: 16, nz: 2, T });
    const s = env.surface;
    const cfg = TEMPORAL("last");
    const codes = ingestCodes(s.frames, s.shape.channels, [...ENV_EPS], cfg.G);
    const r = encodeIntScp4d(inputOf(s, [...ENV_EPS]), codes, cfg);
    const d = decodeIntScp4d(r.bytes, s.relations);
    return { id: `env-16x16x2-T${T}-temporal-last`, T, D: codes[0].length, bytes: r.bytes, codes: d.codes.map((f) => Array.from(f)), perFrame: d.perFrame, decode_ops: { ...d.ops } };
  });
}

// ---------- simulator inputs ----------
const w32 = (v: number) => ((v < 0 ? v + 2 ** 32 : v) >>> 0).toString(16).padStart(8, "0");
export function simFiles(bytes: Uint8Array, codes: readonly (readonly number[])[], eventsPerFrame: readonly number[]): { stream: string; codes: string; events: string } {
  for (const f of codes) for (const v of f) if (!Number.isInteger(v) || v < -(2 ** 31) || v >= 2 ** 31) throw new RangeError("code outside 32-bit");
  return {
    stream: Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("\n") + "\n",
    codes: codes.flatMap((f) => f.map(w32)).join("\n") + "\n",
    events: eventsPerFrame.map(w32).join("\n") + "\n",
  };
}

// ---------- stream structure + RTL cycle model ----------
export interface StreamStructure {
  bytes: number; T: number; D: number; G: number; predictor: number; rank: number; relations: number;
  /** bytes up to and including the high byte of C (index 16) */
  fixed_bytes: number;
  /** header bytes after the C field, up to and including the layout byte */
  header_tail_bytes: number;
  payload_bytes: number;
  sparse_frames: number; dense_frames: number; events: number;
  /** element tokens a zero/linear decoder must sweep without a byte (sparse frames only) */
  sweep_tokens: number;
}

function readU(buf: Uint8Array, i: number): [number, number] {
  let n = 0, s = 0;
  for (;;) { const b = buf[i++]; n += (b & 0x7f) * 2 ** s; if ((b & 0x80) === 0) return [n, i]; s += 7; }
}

/** Walks an S4DI v1 temporal-only stream (no relations, rank 0) and returns its structure. */
export function streamStructure(buf: Uint8Array): StreamStructure {
  let i = 5;
  const T = buf[i] + buf[i + 1] * 256 + buf[i + 2] * 65536 + buf[i + 3] * 16777216; i += 4;
  const sh = [0, 1, 2, 3].map((k) => buf[i + 2 * k] + 256 * buf[i + 2 * k + 1]); i += 8;
  const D = sh[0] * sh[1] * sh[2] * sh[3], C = sh[3];
  const fixed = i;
  i += 8 * C;
  const G = buf[i++];
  for (let k = 0; k < T; k++) i = readU(buf, i)[1];
  if (buf[i++] === 1) { for (let k = 0; k < T; k++) i = readU(buf, i)[1]; i += T; }
  const rank = buf[i++], relations = buf[i++], predictor = buf[i++]; i++;
  const allDense = buf[i++] === 1;
  const headerEnd = i;
  let sparse = 0, dense = 0, events = 0, sweep = 0;
  for (let t = 0; t < T; t++) {
    let isDense = true, n = 0;
    if (!allDense) { const [h, j] = readU(buf, i); i = j; n = Math.floor(h / 2); isDense = h % 2 === 1; }
    if (isDense) {
      dense++;
      for (let e = 0; e < D; e++) { const [u, j] = readU(buf, i); i = j; if (u !== 0) events++; }
    } else {
      sparse++; events += n;
      for (let k = 0; k < n; k++) { i = readU(buf, i)[1]; i = readU(buf, i)[1]; } // (index or gap, q) per event
      sweep += D - n;
    }
  }
  if (i !== buf.length) throw new RangeError("stream structure walk did not end at the last byte");
  return { bytes: buf.length, T, D, G, predictor, rank, relations, fixed_bytes: fixed, header_tail_bytes: headerEnd - fixed, payload_bytes: buf.length - headerEnd,
    sparse_frames: sparse, dense_frames: dense, events, sweep_tokens: sweep };
}

/**
 * RTL cycle model (full-rate input, no bubbles), counted the way the testbench counts: from the
 * first cycle after reset to the cycle `done` is observed, inclusive.
 *   cycles = bytes + clear_stall + sweep + RTL_DRAIN
 *   clear_stall = max(0, D − header_tail_bytes): the D-cycle state clear starts on the cycle the
 *   C field completes and overlaps the rest of the header; the first payload byte waits for it.
 *   sweep = element tokens of sparse frames that carry no byte (zero / linear predictors only;
 *   the last-value hold is event-driven and never sweeps).
 */
export function rtlCycleModel(s: StreamStructure): { cycles: number; clear_stall: number; sweep: number; drain: number } {
  const clear_stall = Math.max(0, s.D - s.header_tail_bytes);
  const sweep = s.predictor === 1 ? 0 : s.sweep_tokens;
  return { cycles: s.bytes + clear_stall + sweep + RTL_DRAIN, clear_stall, sweep, drain: RTL_DRAIN };
}
